@startuml

class HBMS {
  + CalculateReliabilityRating(traveller: Traveller): float
}

class Traveller {
  + Name : string
  + CompanyName : string
  + Address : string
  + TravelPreferences : string[]
}

class Hotel {
  + Name : string
  + Address : string
  + Rating : int
}

class HotelChain {
  + Name : string
}

class City {
  + Name : string
}

class RoomType {
  + Type : string
}

class Availability {
  + Period : string
}

class SearchCriteria {
  + City : string
  + ArrivalDate : date
  + DepartureDate : date
  + NumberOfRooms : int
  + RoomType : string
  + MinimumRating : int
  + MaxCostPerNight : float
  + Preferences : string[]
}

class PreliminaryBooking {
  + BookingIdentifier : string
  + Price : float
  + CityArea : string
  + HotelRating : int
  + KeyPreferences : string[]
}

class SpecialOffer {
  + Price : float
}

class Booking {
  + CreditCardInfo : string
  + CancellationDeadline : date
  + IsPrePaid : boolean
  + IsConfirmed : boolean
}

class HotelConfirmation {
  + ConfirmationTime : datetime
}

Hotel "0..*" -- "1" City
Hotel "0..*" -- "0..1" HotelChain
Hotel "1" -- "0..*" Availability
Availability "1" -- "1" RoomType
Hotel "1" -- "0..*" Booking
Traveller "1" -- "0..*" Booking
Traveller "1" -- "0..*" PreliminaryBooking
PreliminaryBooking "1" -- "0..*" SpecialOffer
PreliminaryBooking "1" -- "0..*" Hotel
Hotel "1" -- "0..*" HotelConfirmation
Booking "1" -- "0..1" HotelConfirmation

@enduml

